window.SST_P2_CH5_FALLBACK = {"chapter": "Chapter 5: Citizenship: Rights and Duties", "source": "NCERT Class 8 Social Science (Exploring Society: India and Beyond — Part 2) & BHU CHS Class 9 Entrance Exam Level", "totalQuestions": 160, "questions": [{"id": 1, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Easy", "question": "Who is a 'citizen' of a country in a democracy?", "options": ["Only government ministers and judges", "Only people who own large factories", "A person who legally belongs to a country and can participate in its political decision-making", "Anyone who visits a country for a two-week holiday"], "correctIndex": 2, "explanation": "A citizen holds formal legal membership in a country, enjoys constitutional rights like voting, and shares duties toward the nation.", "ncertRef": "CHS Core • Meaning of Citizenship"}, {"id": 2, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Easy", "question": "What is the key difference between a 'resident' and a 'citizen'?", "options": ["A citizen can never live abroad as a resident elsewhere", "Residents pay taxes but citizens never pay taxes", "Living in a place makes you a resident, whereas citizenship is a formal legal membership in a country", "Every resident is automatically a citizen with voting rights"], "correctIndex": 2, "explanation": "Not every resident of a country is its citizen, and an Indian citizen living abroad for study or work remains an Indian citizen.", "ncertRef": "CHS Exam Favorite • Resident vs Citizen"}, {"id": 3, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Easy", "question": "Who famously said: 'The true source of rights is duty'?", "options": ["Dr. B. R. Ambedkar", "Sardar Vallabhbhai Patel", "Jawaharlal Nehru", "Mahatma Gandhi"], "correctIndex": 3, "explanation": "Mahatma Gandhi emphasized that rights flow naturally when citizens honestly perform their duties toward society.", "ncertRef": "CHS High-Yield • Famous Quotes"}, {"id": 4, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Medium", "question": "Citizenship is described as BOTH a legal identity and a:", "options": ["Private business contract", "Social responsibility", "Temporary school pass", "Military rank"], "correctIndex": 1, "explanation": "As a legal identity it connects a person to the nation, and as a social responsibility it builds belonging, care, and unity.", "ncertRef": "CHS Core • Dual Nature of Citizenship"}, {"id": 5, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Medium", "question": "Which Indian law primarily sets the rules for acquiring and losing Indian citizenship?", "options": ["The Citizenship Act of 1955 (along with its later amendments, including 2019)", "The Indian Penal Code of 1860", "The Motor Vehicles Act of 1988", "The Factory Act of 1948"], "correctIndex": 0, "explanation": "Parliament regulates Indian citizenship mainly through the Citizenship Act, 1955 and its amendments such as the Citizenship (Amendment) Act, 2019.", "ncertRef": "CHS Exam Favorite • Citizenship Laws"}, {"id": 6, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Easy", "question": "Under the Constitution of India, all Indian citizens are:", "options": ["Allowed rights only in their birth state", "Equal before the law regardless of language, religion, caste, or culture", "Divided into unequal classes by wealth", "Given voting rights only if they speak Hindi"], "correctIndex": 1, "explanation": "Indian citizenship guarantees equal constitutional status and dignity to every citizen across all regions and backgrounds.", "ncertRef": "CHS Core • Constitutional Equality"}, {"id": 7, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Easy", "question": "Which of the following is a civic DUTY of an Indian citizen rather than a right?", "options": ["Right to free education up to age 14", "Obeying the law, paying taxes, and protecting public property", "Freedom of speech and expression", "Right to approach the Supreme Court"], "correctIndex": 1, "explanation": "Obeying laws, paying taxes, and caring for public spaces are duties; freedoms and legal remedies are rights.", "ncertRef": "CHS Core • Rights vs Duties"}, {"id": 8, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Medium", "question": "Why are citizens' rights like free speech NOT unlimited?", "options": ["Because rights apply only on national holidays", "Because rights come with reasonable limits so they do not harm other people or the nation", "Because citizens have no right to question unfair practices", "Because only adults over 60 have full speech rights"], "correctIndex": 1, "explanation": "Reasonable restrictions ensure one person's freedom does not violate another person's safety, dignity, or public order.", "ncertRef": "CHS Conceptual • Limits on Rights"}, {"id": 9, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Easy", "question": "Which four core concepts are specifically highlighted in Class 8 civics to understand citizenship in everyday life?", "options": ["Metals, Non-metals, Acids, and Bases", "Rivers, Plateaus, Plains, and Oceans", "Rights, Duties, Discrimination, and Inclusion", "Taxes, Exports, Tariffs, and Monopolies"], "correctIndex": 2, "explanation": "Rights, duties, and discrimination are addressed in the Constitution, while inclusion is the active way we ensure no one is left out.", "ncertRef": "CHS Core • Core Pillars"}, {"id": 10, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Medium", "question": "When a new student is teased on the school playground for their accent and two classmates stand up to stop the bullies and invite them to play, they are showing:", "options": ["Indifference to school rules", "Misuse of authority", "Legal discrimination", "Active, inclusive citizenship in everyday life"], "correctIndex": 3, "explanation": "Good citizenship begins in daily life by standing against unfairness and welcoming others with respect.", "ncertRef": "CHS Application • Everyday Citizenship"}, {"id": 11, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Easy", "question": "Which of the following best describes 'justified claims' in the context of human and citizen rights?", "options": ["Special privileges only for wealthy families", "Anything a person desires, even if it hurts someone else", "Basic freedoms and needs essential for living with dignity, safety, and respect — without harming others", "Rules made only for foreign tourists"], "correctIndex": 2, "explanation": "Not every wish is a right; true rights are justified claims that protect human dignity and well-being for all.", "ncertRef": "CHS Core • Meaning of Rights"}, {"id": 12, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Medium", "question": "Can a person reside in India for work without being an Indian citizen?", "options": ["No — anyone staying one month automatically becomes a citizen", "Yes, and they automatically vote in Lok Sabha elections", "Yes — a foreign national living in India on a valid visa is a resident, not a citizen", "No — only Indian citizens are allowed to enter India"], "correctIndex": 2, "explanation": "Residence refers to where you live; citizenship is formal legal membership granting political rights like voting.", "ncertRef": "CHS Conceptual • Resident vs Citizen"}, {"id": 13, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Easy", "question": "What does 'active participation' as a citizen include?", "options": ["Damaging public buses during protests", "Staying silent when someone is bullied", "Voting, following laws, helping those in need, keeping surroundings clean, and questioning unfair practices", "Refusing to pay taxes while using public roads"], "correctIndex": 2, "explanation": "Active citizenship blends fulfilling everyday responsibilities with speaking up peacefully for fairness.", "ncertRef": "CHS Core • Active Citizenship"}, {"id": 14, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Medium", "question": "If an Indian citizen moves to another country temporarily for higher studies, what happens to their Indian citizenship?", "options": ["They lose all Fundamental Rights permanently", "They become a citizen of every country they visit", "They lose Indian citizenship the day they board the flight", "They remain an Indian citizen even while residing abroad"], "correctIndex": 3, "explanation": "Citizenship is a legal tie to one's country that does not vanish merely because a citizen resides temporarily overseas.", "ncertRef": "CHS Conceptual • Citizenship"}, {"id": 15, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Easy", "question": "In India, which type of government gives citizens the power to participate in decision-making by electing representatives?", "options": ["Military dictatorship", "Absolute monarchy", "Colonial rule", "Democracy"], "correctIndex": 3, "explanation": "Democracy literally means rule by the people, where citizens choose their leaders and hold them accountable.", "ncertRef": "CHS Core • Democracy"}, {"id": 16, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Medium", "question": "Which statement about the relationship between citizenship and the Constitution of India is TRUE?", "options": ["Citizens can never approach courts against government actions", "The Constitution only protects government officers, not ordinary citizens", "The Constitution protects citizens from unfair treatment both by other people and by the government", "Rights in the Constitution are merely optional wishes"], "correctIndex": 2, "explanation": "Fundamental Rights limit misuse of power and empower citizens to seek justice in court if their rights are violated.", "ncertRef": "CHS Core • Constitutional Protection"}, {"id": 17, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Easy", "question": "Which of the following actions CANNOT be claimed as a 'right'?", "options": ["Going to school up to age 14", "Playing loud music at midnight that disturbs sick neighbours and students", "Speaking your views respectfully", "Practising your chosen religion peacefully"], "correctIndex": 1, "explanation": "Actions that harm others' health, peace, or rights cannot be defended as rights.", "ncertRef": "CHS Application • Limits of Rights"}, {"id": 18, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Medium", "question": "Which of the following is an affirmative way of ensuring non-discrimination in schools and communities?", "options": ["Inclusion — actively welcoming and supporting everyone regardless of background or ability", "Building staircases only, with no wheelchair ramps", "Creating separate rules to exclude girls from debates", "Ignoring students who speak a different regional language"], "correctIndex": 0, "explanation": "Inclusion removes practical and social barriers so every member of society can participate fully.", "ncertRef": "CHS Core • Inclusion"}, {"id": 19, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Hard", "question": "Which combination correctly pairs the concept with its meaning?", "options": ["Rights: Optional favours | Duties: Punishments for crime | Inclusion: Excluding minorities", "Rights: Only for adults | Duties: Only for soldiers | Inclusion: Only for rich cities", "Rights: Freedoms for dignity | Duties: Moral & social responsibilities | Inclusion: Ensuring no one is left out", "Discrimination: Fair treatment | Equity: Ignoring differences | Citizen: Any tourist"], "correctIndex": 2, "explanation": "Rights protect dignity, duties guide responsible action, and inclusion ensures equal participation for all.", "ncertRef": "CHS Match Check • Core Terms"}, {"id": 20, "topic": "Who Is a Citizen? Identity & Acts", "difficulty": "Hard", "question": "Assertion (A): Citizenship is both a legal status and an everyday social responsibility.\nReason (R): While the law grants voting and legal rights, society thrives only when citizens also respect others, follow rules, and help their community.", "options": ["Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true", "Both A and R are true, and R is the correct explanation of A"], "correctIndex": 3, "explanation": "Legal status alone is incomplete without active, empathetic participation in community life.", "ncertRef": "CHS Assertion-Reason • Citizenship"}, {"id": 21, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Easy", "question": "How many broad categories of Fundamental Rights are guaranteed by the Constitution of India?", "options": ["Four", "Eleven", "Six", "Eight"], "correctIndex": 2, "explanation": "The six Fundamental Rights are: Right to Equality, Right to Freedom, Right against Exploitation, Right to Freedom of Religion, Cultural & Educational Rights, and Right to Constitutional Remedies.", "ncertRef": "CHS Exam Favorite • Six Fundamental Rights"}, {"id": 22, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Easy", "question": "Under which Articles of the Indian Constitution is the 'Right to Equality' placed?", "options": ["Articles 14 to 18", "Articles 25 to 28", "Articles 23 to 24", "Articles 19 to 22"], "correctIndex": 0, "explanation": "Articles 14–18 guarantee equality before law, non-discrimination, equal job opportunity, abolition of untouchability, and abolition of titles.", "ncertRef": "CHS Exam Favorite • Articles 14–18"}, {"id": 23, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Easy", "question": "Which Fundamental Right ensures that every person — rich or poor, citizen or leader — is treated equally before the law?", "options": ["Cultural and Educational Rights", "Right to Freedom of Religion", "Right against Exploitation", "Right to Equality (Article 14)"], "correctIndex": 3, "explanation": "Article 14 guarantees 'equality before the law' and equal protection of the laws for all persons.", "ncertRef": "CHS Core • Article 14"}, {"id": 24, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Easy", "question": "Which Article of the Constitution prohibits discrimination on grounds of religion, race, caste, sex, or place of birth?", "options": ["Article 32", "Article 15", "Article 21A", "Article 17"], "correctIndex": 1, "explanation": "Article 15 ensures no citizen can be denied access to shops, public places, libraries, or schools based on religion, race, caste, sex, or birthplace.", "ncertRef": "CHS Exam Favorite • Article 15"}, {"id": 25, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Easy", "question": "Which evil social practice is strictly abolished and made a punishable offence under Article 17 of the Constitution?", "options": ["Untouchability", "Wearing traditional dress", "Forming reading clubs", "Paying income tax"], "correctIndex": 0, "explanation": "Article 17 abolishes untouchability in any form and forbids its practice.", "ncertRef": "CHS Exam Favorite • Article 17"}, {"id": 26, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Medium", "question": "Which Article ensures equal opportunity for all citizens in matters of public (government) employment?", "options": ["Article 29", "Article 16", "Article 18", "Article 24"], "correctIndex": 1, "explanation": "Article 16 guarantees equality of opportunity in public employment without unfair discrimination.", "ncertRef": "CHS High-Yield • Article 16"}, {"id": 27, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Medium", "question": "Article 18 abolishes the State from conferring hereditary or special titles (like 'Rai Bahadur' or 'Sir'), EXCEPT:", "options": ["Military and academic distinctions (such as Param Vir Chakra, Doctor, or Professor)", "Titles given to wealthy landlords", "Titles based on caste", "Titles bought with money"], "correctIndex": 0, "explanation": "Under Article 18, only military bravery honours and academic degrees/distinctions are permitted.", "ncertRef": "CHS High-Yield • Article 18"}, {"id": 28, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Medium", "question": "How does 'Equity' differ from 'Equality'?", "options": ["Equality gives everyone the exact same support, whereas Equity gives each person the fair support they actually need to succeed", "Equity and Equality mean the exact same thing in every case", "Equality means helping only rich people, whereas Equity means helping no one", "Equality is illegal while Equity is a Fundamental Duty"], "correctIndex": 0, "explanation": "Because people start with different needs or historical disadvantages (like needing a wheelchair ramp or Braille books), equity ensures fair outcomes.", "ncertRef": "CHS Exam Favorite • Equality vs Equity"}, {"id": 29, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Easy", "question": "Which national awareness and support campaign was launched to promote girls' survival, protection, and equal access to education?", "options": ["Swachh Rail Mission", "Make in Space", "Beti Bachao, Beti Padhao", "Digital Currency Drive"], "correctIndex": 2, "explanation": "Beti Bachao, Beti Padhao is an important equity-focused initiative supporting girls' education and challenging gender bias.", "ncertRef": "CHS Core • Equity Initiatives"}, {"id": 30, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Medium", "question": "If a town fair organiser tells a girl she cannot participate in a debate because 'girls should not speak on stage', which Fundamental Right is being violated?", "options": ["Right to Property", "Right to Equality (and Right to Freedom of Speech and Expression)", "Cultural Rights of Minorities", "Right to Freedom of Religion"], "correctIndex": 1, "explanation": "Barred purely because of gender violates non-discrimination under the Right to Equality as well as freedom of expression.", "ncertRef": "CHS Application • Real-Life Rights"}, {"id": 31, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Medium", "question": "If a street vendor's son is stopped from entering a public library stall while a wealthy boy is welcomed inside, this violates:", "options": ["Duty to respect the National Flag", "Right to Freedom of Religion", "Article 51A", "Right to Equality and non-discrimination"], "correctIndex": 3, "explanation": "Public spaces and educational stalls must be open equally to all children regardless of economic background.", "ncertRef": "CHS Application • Real-Life Rights"}, {"id": 32, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Easy", "question": "Why are Fundamental Rights described as 'enforceable by law' (justiciable)?", "options": ["Because if they are violated, citizens can approach the courts for justice and protection", "Because Parliament can delete all rights every week", "Because they apply only inside police stations", "Because citizens must pay a fine to enjoy them"], "correctIndex": 0, "explanation": "Enforceability means courts have the legal power to restore and protect Fundamental Rights when breached.", "ncertRef": "CHS Core • Justiciability"}, {"id": 33, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Medium", "question": "Which of the following is an example of EQUITY rather than simple identical equality?", "options": ["Giving everyone a stool of the exact same height even when one person is much shorter", "Providing Braille textbooks and tactile maps to visually impaired students in a school", "Charging the same bus fare to toddlers and adults", "Giving every student the exact same printed small-font book regardless of eyesight"], "correctIndex": 1, "explanation": "Equity provides tailored support (like Braille books or ramps) so differently abled students enjoy equal learning opportunities.", "ncertRef": "CHS Conceptual • Equity"}, {"id": 34, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Easy", "question": "Which Fundamental Right prevents the government from granting aristocratic titles like 'Maharaja' or 'Knight' to citizens?", "options": ["Right to Constitutional Remedies (Article 32)", "Right to Equality (Article 18)", "Right to Life (Article 21)", "Right to Freedom (Article 19)"], "correctIndex": 1, "explanation": "Abolition of titles under Article 18 reinforces equal status among all citizens in a republic.", "ncertRef": "CHS Core • Article 18"}, {"id": 35, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Medium", "question": "In the Constitution of India, Fundamental Rights are placed in:", "options": ["The Eighth Schedule", "Part IV-A (Article 51A)", "Part III (Articles 12 to 35; core six rights in Articles 14–32)", "Part I (Articles 1 to 4)"], "correctIndex": 2, "explanation": "Part III of the Constitution contains Fundamental Rights, while Part IV-A contains Fundamental Duties.", "ncertRef": "CHS High-Yield • Constitutional Structure"}, {"id": 36, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Hard", "question": "Match the Article with its guarantee:\n(i) Article 14 — (ii) Article 15 — (iii) Article 17", "options": ["(i) Freedom of speech — (ii) Minority schools — (iii) Fundamental duties", "(i) Child labour ban — (ii) Free education — (iii) Supreme Court remedies", "(i) Abolition of titles — (ii) Right to life — (iii) Religious freedom", "(i) Equality before law — (ii) No discrimination — (iii) Abolition of untouchability"], "correctIndex": 3, "explanation": "Article 14 ensures equality before law, Article 15 bars discrimination, and Article 17 abolishes untouchability.", "ncertRef": "CHS Match Check • Articles 14–17"}, {"id": 37, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Easy", "question": "Do Fundamental Rights protect citizens ONLY against unfair treatment by private individuals, or also against unfair actions by the government?", "options": ["Neither; they are only moral suggestions", "Only against foreign tourists", "Against unfair actions by BOTH private individuals/groups AND the government", "Only against private shopkeepers"], "correctIndex": 2, "explanation": "Fundamental Rights act as a shield against arbitrary power whether exercised by state authorities or others.", "ncertRef": "CHS Conceptual • Scope of Rights"}, {"id": 38, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Medium", "question": "Why might giving the exact same support to everyone sometimes fail to produce fairness?", "options": ["Because the Constitution forbids helping anyone", "Because individuals may start with different needs, disabilities, or historical disadvantages", "Because equality means everyone must wear identical clothes at home", "Because courts do not allow ramps in schools"], "correctIndex": 1, "explanation": "Equity recognizes different starting points and gives fair extra support where needed.", "ncertRef": "CHS Conceptual • Equity"}, {"id": 39, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Easy", "question": "Which of the following grounds of discrimination is explicitly banned under Article 15?", "options": ["Medical qualification for becoming a surgeon", "Exam marks in mathematics", "Age eligibility for a driving licence", "Religion, race, caste, sex, or place of birth"], "correctIndex": 3, "explanation": "Fair merit or safety rules (like medical degrees for doctors) are valid, while identity-based discrimination (caste, religion, race, sex, birthplace) is banned.", "ncertRef": "CHS Core • Article 15"}, {"id": 40, "topic": "Fundamental Rights & Right to Equality", "difficulty": "Hard", "question": "Assertion (A): Providing a wheelchair ramp at the entrance of an exhibition hall is an example of both Equity and Inclusion.\nReason (R): Without a ramp, a wheelchair user cannot enjoy the same access as others even if the hall door is technically open to all.", "options": ["Both A and R are true, but R is NOT the correct explanation of A", "Both A and R are true, and R is the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctIndex": 1, "explanation": "True equality of access requires removing physical barriers so persons with disabilities can participate with dignity.", "ncertRef": "CHS Assertion-Reason • Equity & Inclusion"}, {"id": 41, "topic": "Right to Freedom & Right to Life", "difficulty": "Easy", "question": "Which Articles of the Indian Constitution cover the 'Right to Freedom' (including speech, movement, and assembly)?", "options": ["Articles 19 to 22", "Articles 14 to 18", "Articles 23 to 24", "Articles 29 to 30"], "correctIndex": 0, "explanation": "Articles 19–22 protect vital personal freedoms such as speech and expression, peaceful assembly, movement, and protection of life and liberty.", "ncertRef": "CHS Exam Favorite • Articles 19–22"}, {"id": 42, "topic": "Right to Freedom & Right to Life", "difficulty": "Easy", "question": "Which specific Article guarantees freedoms such as freedom of speech and expression, peaceful assembly without arms, and free movement across India?", "options": ["Article 19", "Article 17", "Article 32", "Article 24"], "correctIndex": 0, "explanation": "Article 19(1) lists core democratic freedoms of citizens, subject to reasonable restrictions.", "ncertRef": "CHS High-Yield • Article 19"}, {"id": 43, "topic": "Right to Freedom & Right to Life", "difficulty": "Easy", "question": "Which Article protects 'Life and Personal Liberty', interpreted by courts to mean living with dignity, clean environment, health, and livelihood?", "options": ["Article 29", "Article 21", "Article 18", "Article 14"], "correctIndex": 1, "explanation": "Article 21 ensures no person is deprived of life or personal liberty except according to fair legal procedure, and includes the right to live with human dignity.", "ncertRef": "CHS Exam Favorite • Article 21"}, {"id": 44, "topic": "Right to Freedom & Right to Life", "difficulty": "Easy", "question": "Which Article — inserted by the 86th Constitutional Amendment (2002) — guarantees free and compulsory education for all children aged 6 to 14 years?", "options": ["Article 21A (Right to Education)", "Article 51A(a)", "Article 17", "Article 23"], "correctIndex": 0, "explanation": "Article 21A makes elementary education for every child aged 6–14 a Fundamental Right.", "ncertRef": "CHS Exam Favorite • Article 21A"}, {"id": 45, "topic": "Right to Freedom & Right to Life", "difficulty": "Medium", "question": "What age group is covered under the Right to Free and Compulsory Education (Article 21A)?", "options": ["18 to 25 years", "6 to 14 years", "14 to 18 years", "0 to 3 years"], "correctIndex": 1, "explanation": "Every child between 6 and 14 years has a Fundamental Right to free and compulsory elementary education.", "ncertRef": "CHS Core • Right to Education"}, {"id": 46, "topic": "Right to Freedom & Right to Life", "difficulty": "Medium", "question": "Why does the Right to Freedom of Speech come with 'reasonable restrictions'?", "options": ["To ensure freedom is not misused to spread hate, incite violence, or harm national security and others' rights", "To ban all newspapers and books", "To allow speech only inside Parliament", "To stop citizens from ever criticizing any government policy"], "correctIndex": 0, "explanation": "Democratic freedoms are balanced with responsibility so speech remains peaceful and respectful.", "ncertRef": "CHS Conceptual • Reasonable Restrictions"}, {"id": 47, "topic": "Right to Freedom & Right to Life", "difficulty": "Medium", "question": "In 2017, which Indian High Court declared the rivers Ganga and Yamuna to be 'legal entities' with the rights of a living person (later overturned by the Supreme Court)?", "options": ["Calcutta High Court", "Madras High Court", "Bombay High Court", "Uttarakhand High Court"], "correctIndex": 3, "explanation": "In 2017, the Uttarakhand High Court declared the Ganga and Yamuna living legal entities to protect them, though the Supreme Court later overturned it as legally unsustainable.", "ncertRef": "CHS High-Yield • Rights of Nature"}, {"id": 48, "topic": "Right to Freedom & Right to Life", "difficulty": "Medium", "question": "In which country is the Whanganui River legally recognised and treated as a living being with its own legal rights?", "options": ["New Zealand", "United Kingdom", "Japan", "Australia"], "correctIndex": 0, "explanation": "New Zealand granted legal personhood to the Whanganui River, respecting Indigenous Maori guardianship of the river.", "ncertRef": "CHS High-Yield • Global Examples"}, {"id": 49, "topic": "Right to Freedom & Right to Life", "difficulty": "Medium", "question": "Which Central American country explicitly protects the rights of Nature inside its Constitution?", "options": ["Egypt", "Costa Rica", "France", "Canada"], "correctIndex": 1, "explanation": "Costa Rica is well known globally for embedding environmental and nature protection directly into its constitutional framework.", "ncertRef": "CHS High-Yield • Global Examples"}, {"id": 50, "topic": "Right to Freedom & Right to Life", "difficulty": "Easy", "question": "How does the Right to Life (Article 21) support children with disabilities?", "options": ["By exempting schools from building accessible facilities", "By placing them in isolated rooms away from other students", "By denying them school admission", "By ensuring they receive support such as ramps, tactile maps, and inclusive classrooms to learn, play, and live with dignity"], "correctIndex": 3, "explanation": "Dignity under Article 21 includes equal access to education, healthcare, and a safe environment for children with disabilities.", "ncertRef": "CHS Core • Disability Rights"}, {"id": 51, "topic": "Right to Freedom & Right to Life", "difficulty": "Easy", "question": "Which of the following is now recognised as part of the 'Right to Life with Dignity' under Article 21?", "options": ["Refusing to follow traffic signals", "Driving without a licence", "Clean air and environment, healthcare, education, and livelihood", "Polluting rivers with factory waste"], "correctIndex": 2, "explanation": "Courts have expanded Article 21 beyond mere survival to include clean air, clean water, health, and a dignified life.", "ncertRef": "CHS Core • Scope of Article 21"}, {"id": 52, "topic": "Right to Freedom & Right to Life", "difficulty": "Medium", "question": "If students politely request comfortable sports clothes for outdoor Sports Day races, which right are they exercising?", "options": ["Right against Exploitation", "Abolition of Untouchability", "Right to Constitutional Remedies", "Freedom of speech and expression (Article 19), which should be raised respectfully"], "correctIndex": 3, "explanation": "Expressing constructive ideas peacefully is part of freedom of expression, balanced with respecting school rules and dialogue.", "ncertRef": "CHS Application • Student Rights"}, {"id": 53, "topic": "Right to Freedom & Right to Life", "difficulty": "Medium", "question": "Which teaching aid shown in inclusive schools helps visually impaired students study geography maps using touch?", "options": ["Tactile maps (and Braille books)", "Invisible ink charts", "Silent black-and-white videos only", "Microscopic slides"], "correctIndex": 0, "explanation": "Tactile maps have raised surfaces that blind or low-vision students can feel with their fingertips to enjoy their Right to Education.", "ncertRef": "CHS Core • Inclusive Education"}, {"id": 54, "topic": "Right to Freedom & Right to Life", "difficulty": "Easy", "question": "Which Fundamental Right allows Indian citizens to move freely across any state of India and choose their occupation?", "options": ["Right to Equality (Article 17)", "Right against Exploitation (Article 23)", "Right to Freedom of Religion (Article 25)", "Right to Freedom (Article 19)"], "correctIndex": 3, "explanation": "Article 19 protects freedom of movement, residence, and practising any lawful profession or trade.", "ncertRef": "CHS Core • Article 19"}, {"id": 55, "topic": "Right to Freedom & Right to Life", "difficulty": "Medium", "question": "What reason did the Supreme Court of India give when overturning the Uttarakhand High Court's 2017 order granting human legal rights to the Ganga and Yamuna?", "options": ["It transferred the rivers to Nepal", "It said water is not needed by citizens", "It said rivers do not flow through India", "It called the order 'legally unsustainable'"], "correctIndex": 3, "explanation": "The Supreme Court stayed and overturned the order, holding that treating rivers as legal persons raised practical legal difficulties and was legally unsustainable.", "ncertRef": "CHS High-Yield • Judiciary & Nature"}, {"id": 56, "topic": "Right to Freedom & Right to Life", "difficulty": "Easy", "question": "Under Article 19, citizens have the right to assemble peacefully, provided they do so:", "options": ["Without arms (weapons) and without causing violence", "Only by blocking hospital ambulances", "Only after midnight", "With sticks and stones"], "correctIndex": 0, "explanation": "Peaceful assembly without weapons is a democratic right; violence and blocking emergency services violate public order.", "ncertRef": "CHS Core • Peaceful Assembly"}, {"id": 57, "topic": "Right to Freedom & Right to Life", "difficulty": "Medium", "question": "Why do some environmentalists support giving rivers and forests legal rights similar to human rights?", "options": ["So factories can dump more chemicals freely", "So rivers can vote in Lok Sabha elections", "So legal guardians can defend ecosystems in court against pollution and destruction", "So trees can pay income tax"], "correctIndex": 2, "explanation": "Legal personhood allows guardians to sue polluters directly on behalf of a river or forest ecosystem.", "ncertRef": "CHS Conceptual • Environmental Ethics"}, {"id": 58, "topic": "Right to Freedom & Right to Life", "difficulty": "Easy", "question": "If an Indian citizen from Uttar Pradesh moves to Maharashtra or Tamil Nadu to work and live, which right protects this?", "options": ["Abolition of Titles", "Right against Exploitation", "Cultural Rights of Minorities only", "Right to Freedom (Article 19)"], "correctIndex": 3, "explanation": "Article 19 guarantees freedom to move freely and settle in any part of India.", "ncertRef": "CHS Application • Article 19"}, {"id": 59, "topic": "Right to Freedom & Right to Life", "difficulty": "Hard", "question": "Which pair of Constitutional Articles matches 'Right to Life' and 'Right to Education (6–14 years)' respectively?", "options": ["Article 23 and Article 24", "Article 21 and Article 21A", "Article 29 and Article 30", "Article 14 and Article 15"], "correctIndex": 1, "explanation": "Article 21 protects life and personal liberty, while Article 21A guarantees free and compulsory education for children aged 6–14.", "ncertRef": "CHS Exam Drill • Articles"}, {"id": 60, "topic": "Right to Freedom & Right to Life", "difficulty": "Hard", "question": "Assertion (A): Freedom of speech gives a citizen the right to express disagreement with a law peacefully.\nReason (R): Freedom of speech also permits spreading false rumours that cause riots.", "options": ["A is false, but R is true", "Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false"], "correctIndex": 3, "explanation": "Peaceful criticism is protected, whereas inciting violence or riots violates reasonable restrictions on free speech.", "ncertRef": "CHS Assertion-Reason • Freedom of Speech"}, {"id": 61, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Easy", "question": "Which Articles of the Constitution guarantee the 'Right against Exploitation'?", "options": ["Articles 23 and 24", "Articles 19 and 22", "Articles 14 and 18", "Articles 25 and 28"], "correctIndex": 0, "explanation": "Article 23 bans human trafficking and forced/bonded labour, while Article 24 prohibits employing children below 14 in hazardous work.", "ncertRef": "CHS Exam Favorite • Articles 23–24"}, {"id": 62, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Easy", "question": "What does 'exploitation' mean in the context of human rights?", "options": ["Planting trees in a colony park", "Taking unfair advantage of others by denying them basic respect, fair wages, liberty, and rights", "Helping a classmate with homework", "Paying workers fair wages for safe work"], "correctIndex": 1, "explanation": "Exploitation includes bonded labour, human trafficking, abuse, and forcing children to work instead of attending school.", "ncertRef": "CHS Core • Meaning of Exploitation"}, {"id": 63, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Easy", "question": "Below what age is employing children generally prohibited in India — especially in factories, mines, or hazardous workplaces?", "options": ["10 years", "25 years", "21 years", "14 years"], "correctIndex": 3, "explanation": "Under the Right against Exploitation (Article 24) and child labour laws, children below 14 cannot be employed in factories, mines, or hazardous jobs.", "ncertRef": "CHS Exam Favorite • Child Labour Law"}, {"id": 64, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Easy", "question": "What is the nationwide toll-free emergency helpline number in India for children in distress or facing child labour and abuse?", "options": ["100", "1080", "Childline 1098", "1950"], "correctIndex": 2, "explanation": "Childline 1098 (easy to remember by counting backwards from 10: 10-9-8) operates across India to rescue and protect children.", "ncertRef": "CHS Exam Favorite • Childline 1098"}, {"id": 65, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Medium", "question": "Under Indian law, when is a child below 14 years permitted to help out in a non-hazardous family enterprise?", "options": ["During midnight shifts in restaurants", "Full-time instead of going to school", "Inside fireworks factories and coal mines", "Only after school hours or during vacations, without harming their education or safety"], "correctIndex": 3, "explanation": "Children may lightly assist a safe, non-hazardous family business only outside school hours or during holidays.", "ncertRef": "CHS High-Yield • Child Protection Rules"}, {"id": 66, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Easy", "question": "Forcing a person to work against their will without fair wages to repay a debt is called:", "options": ["Inclusive education", "Bonded labour (forced labour)", "Voluntary community service", "Active citizenship"], "correctIndex": 1, "explanation": "Bonded labour (begar) is strictly banned under Article 23 of the Constitution.", "ncertRef": "CHS Core • Article 23"}, {"id": 67, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Easy", "question": "Buying, selling, or trading human beings for profit is known as:", "options": ["Civic participation", "Human trafficking", "Cultural exchange", "Equity"], "correctIndex": 1, "explanation": "Human trafficking is a grave crime prohibited unconditionally under Article 23.", "ncertRef": "CHS Core • Article 23"}, {"id": 68, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Medium", "question": "Why do children need special constitutional protection against exploitation?", "options": ["Because children are not Indian citizens until age 30", "Because children cannot speak any language", "Because they depend on adults for safety, may not know their rights, and working deprives them of education, play, and healthy growth", "Because children do not need education"], "correctIndex": 2, "explanation": "Childhood is meant for learning, play, and growth; child labour steals a child's future and health.", "ncertRef": "CHS Conceptual • Child Rights"}, {"id": 69, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Medium", "question": "In 2015, after a concerned citizen called Childline 1098, 20 children forced to work in an unhealthy embroidery factory were rescued. This shows:", "options": ["That Childline 1098 works only in one city", "That factories are allowed to employ children aged 8", "How one responsible citizen's action using legal helplines can protect children's Fundamental Rights", "That citizens should ignore child labour"], "correctIndex": 2, "explanation": "Active citizens protect vulnerable children by reporting exploitation to teachers, police, or Childline 1098.", "ncertRef": "CHS Application • Childline Impact"}, {"id": 70, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Easy", "question": "If you see a 10-year-old child forced to work in a welding shop or roadside tea stall instead of attending school, which Fundamental Right is being violated?", "options": ["Abolition of Titles", "Right to Freedom of Religion", "Cultural Rights of Minorities", "Right against Exploitation (and Right to Education)"], "correctIndex": 3, "explanation": "Employing a 10-year-old child denies them both freedom from exploitation (Art. 24) and compulsory education (Art. 21A).", "ncertRef": "CHS Application • Identifying Violations"}, {"id": 71, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Medium", "question": "What is the best immediate step a Class 8 student can take if they notice a child being forced to work in a hazardous workshop?", "options": ["Inform a trusted teacher, principal, parents, or call/report to Childline 1098", "Hire the child to do their own homework", "Argue violently with the shop owner alone at night", "Laugh and walk away"], "correctIndex": 0, "explanation": "Seeking help from adults, school authorities, or Childline 1098 ensures safe, legal rescue of the child.", "ncertRef": "CHS Application • Civic Action"}, {"id": 72, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Medium", "question": "Which of the following workplaces is STRICTLY banned for employing children below 14 years?", "options": ["Participating in a school science club", "Factories, mines, and restaurants", "Watering plants in one's home garden on Sunday", "Reading storybooks in a public library"], "correctIndex": 1, "explanation": "Hazardous and commercial employment in factories, mines, and restaurants is illegal for children under 14.", "ncertRef": "CHS Core • Child Labour Ban"}, {"id": 73, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Medium", "question": "When did Childline 1098 begin before growing into a nationwide helpline?", "options": ["In 2024 as a private video game", "In 1950 inside the Supreme Court", "As an action project at an educational institution in the late 1990s", "In 1857 during the Revolt"], "correctIndex": 2, "explanation": "Childline started as a small field-action project at an educational institution in the late 1990s and expanded nationwide.", "ncertRef": "CHS High-Yield • Childline History"}, {"id": 74, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Easy", "question": "Which Article specifically bans 'traffic in human beings and begar (forced labour)'?", "options": ["Article 19", "Article 23", "Article 30", "Article 16"], "correctIndex": 1, "explanation": "Article 23 outlaws human trafficking and all forms of forced or bonded labour.", "ncertRef": "CHS Core • Article 23"}, {"id": 75, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Easy", "question": "Which Article specifically prohibits the employment of children below 14 years in factories, mines, or hazardous occupations?", "options": ["Article 32", "Article 21", "Article 14", "Article 24"], "correctIndex": 3, "explanation": "Article 24 safeguards children under 14 from hazardous labour.", "ncertRef": "CHS Core • Article 24"}, {"id": 76, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Medium", "question": "During a town festival, volunteers noticed young children cleaning outside the fairground instead of attending school and helped enrol them in school. Which two rights were restored?", "options": ["Right to Vote and Right to Passport", "Right to Religion and Right to Travel Abroad", "Right to Titles and Right to Property", "Right against Exploitation and Right to Education"], "correctIndex": 3, "explanation": "Removing children from labour and enrolling them in school upholds both Art. 24 and Art. 21A.", "ncertRef": "CHS Application • School Enrolment"}, {"id": 77, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Easy", "question": "Which helpline number is famously remembered by counting backwards from 10?", "options": ["1098 (Childline)", "112", "1800", "100"], "correctIndex": 0, "explanation": "10 - 9 - 8 forms 1098, India's dedicated national helpline for children.", "ncertRef": "CHS Core • Childline 1098"}, {"id": 78, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Medium", "question": "Why is employing children at very low wages considered exploitation even if the child's family is poor?", "options": ["Because poor families do not have Fundamental Rights", "Because children earn more than adult engineers", "Because schools charge crores of rupees", "Because poverty cannot justify denying children safety, health, fair dignity, and their constitutional Right to Education"], "correctIndex": 3, "explanation": "The State and society must support poor families and enrol children in free schooling rather than pushing children into labour.", "ncertRef": "CHS Conceptual • Child Rights"}, {"id": 79, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Hard", "question": "Find the ODD one out among practices prohibited by the Right against Exploitation (Articles 23–24):", "options": ["Bonded labour without wages", "Employing 11-year-olds in a firecracker factory", "Voluntary Sunday colony clean-up by families", "Human trafficking"], "correctIndex": 2, "explanation": "Voluntary neighbourhood cleanliness is a civic duty, whereas bonded labour, trafficking, and child labour are illegal forms of exploitation.", "ncertRef": "CHS Odd-One-Out • Exploitation"}, {"id": 80, "topic": "Right Against Exploitation & Child Protection", "difficulty": "Hard", "question": "Assertion (A): Children below 14 years are banned from working in mines and factories.\nReason (R): Hazardous work harms their health and deprives them of their Fundamental Right to Education and a safe childhood.", "options": ["A is false, but R is true", "Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false"], "correctIndex": 1, "explanation": "Article 24 and Article 21A work hand in hand to keep children safe in classrooms rather than dangerous workplaces.", "ncertRef": "CHS Assertion-Reason • Child Labour"}, {"id": 81, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Easy", "question": "Which Articles of the Constitution guarantee the 'Right to Freedom of Religion'?", "options": ["Articles 25 to 28", "Articles 23 to 24", "Articles 14 to 18", "Articles 19 to 22"], "correctIndex": 0, "explanation": "Articles 25–28 give every person freedom of conscience and the right to freely profess, practise, and propagate their religion.", "ncertRef": "CHS Exam Favorite • Articles 25–28"}, {"id": 82, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Easy", "question": "Under the Right to Freedom of Religion, can government-run schools promote or compel students to follow any one particular religion?", "options": ["Only on Fridays and Sundays", "Yes — if the school principal orders it", "No — state-run schools are not allowed to promote any particular religion", "Yes — they must promote the majority religion"], "correctIndex": 2, "explanation": "India is a secular democracy; government-funded schools treat all religions equally without promoting any single faith.", "ncertRef": "CHS Core • Secularism in Schools"}, {"id": 83, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Easy", "question": "Which Articles protect the 'Cultural and Educational Rights' of citizens and minorities?", "options": ["Articles 29 and 30", "Articles 21 and 21A", "Articles 23 and 24", "Articles 14 and 15"], "correctIndex": 0, "explanation": "Articles 29–30 protect distinct languages, scripts, and cultures and allow religious and linguistic minorities to establish and manage their own educational institutions.", "ncertRef": "CHS Exam Favorite • Articles 29–30"}, {"id": 84, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Medium", "question": "Under Cultural and Educational Rights, can any student be denied admission to a government-funded school or college because of their religion, caste, race, or language?", "options": ["No — denial of admission on such grounds is strictly prohibited", "Yes — only if they speak a regional language", "Only in science colleges", "Yes — if they belong to a minority community"], "correctIndex": 0, "explanation": "Article 29(2) ensures equal access to state-aided educational institutions for every citizen.", "ncertRef": "CHS Core • Educational Equality"}, {"id": 85, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Easy", "question": "Which right allows religious and linguistic minorities to set up and administer their own schools to preserve their language, script, and culture?", "options": ["Fundamental Duties (Article 51A)", "Cultural and Educational Rights (Article 30)", "Right against Exploitation (Article 23)", "Right to Equality (Article 18)"], "correctIndex": 1, "explanation": "Article 30 empowers minority communities to establish and manage educational institutions of their choice.", "ncertRef": "CHS High-Yield • Minority Rights"}, {"id": 86, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Easy", "question": "Which Fundamental Right gives citizens the power to approach the Supreme Court directly if any of their Fundamental Rights are violated?", "options": ["Right to Freedom of Religion (Article 25)", "Right against Exploitation (Article 24)", "Right to Equality (Article 14)", "Right to Constitutional Remedies (Article 32)"], "correctIndex": 3, "explanation": "Article 32 makes Fundamental Rights real and enforceable by allowing citizens to seek Supreme Court writs/remedies.", "ncertRef": "CHS Exam Favorite • Article 32"}, {"id": 87, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Easy", "question": "Who called the Right to Constitutional Remedies (Article 32) 'the very soul of the Constitution and the very heart of it'?", "options": ["Mahatma Gandhi", "Dr. B. R. Ambedkar", "Subhas Chandra Bose", "Rabindranath Tagore"], "correctIndex": 1, "explanation": "Dr. B. R. Ambedkar told the Constituent Assembly that without Article 32 to enforce rights, the Constitution would be a nullity.", "ncertRef": "CHS Exam Favorite • Dr. B. R. Ambedkar"}, {"id": 88, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Medium", "question": "Why did Dr. B. R. Ambedkar describe Article 32 as the 'heart and soul' of the Constitution?", "options": ["Because Article 32 abolishes all courts in India", "Because Article 32 decides the National Anthem", "Because Article 32 lists all 11 Fundamental Duties", "Because without a legal way to enforce rights in court, Fundamental Rights would remain empty promises on paper"], "correctIndex": 3, "explanation": "A right without a remedy is useless; Article 32 guarantees judicial protection whenever rights are violated.", "ncertRef": "CHS Conceptual • Article 32"}, {"id": 89, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Medium", "question": "Under the Right to Freedom of Religion, can anyone be forced to pay taxes specifically meant for promoting one particular religion?", "options": ["Yes — only in coastal states", "No — the Constitution ensures no one is forced to fund or follow any particular religion", "Yes — every citizen must pay a temple or church tax", "Only students must pay it"], "correctIndex": 1, "explanation": "Freedom of religion protects conscience and forbids compulsory taxation for promoting any specific religion.", "ncertRef": "CHS High-Yield • Religious Freedom"}, {"id": 90, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Medium", "question": "How do Cultural and Educational Rights strengthen India's unity?", "options": ["By forcing everyone to speak only one language", "By respecting India's rich diversity of languages, scripts, and traditions so every community feels valued", "By banning traditional festivals", "By closing all regional libraries"], "correctIndex": 1, "explanation": "Protecting diverse cultures and mother tongues makes minorities and regional groups feel secure and included in the nation.", "ncertRef": "CHS Conceptual • Unity in Diversity"}, {"id": 91, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Easy", "question": "Respecting people of all faiths and not mocking anyone's prayers or festivals reflects:", "options": ["India's constitutional commitment to Freedom of Religion and harmony", "Discrimination", "Abolition of education", "Forced labour"], "correctIndex": 0, "explanation": "Tolerance and mutual respect among all faiths keep a diverse democracy peaceful.", "ncertRef": "CHS Core • Religious Harmony"}, {"id": 92, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Medium", "question": "Why do some debates arise around minority educational protections under Article 30?", "options": ["Because minority schools are not allowed to teach mathematics", "Because minorities are banned from voting in India", "Some people wonder whether special safeguards for minority groups conflict with uniform secular rules, while others see them as essential to protect minority identity", "Because Article 30 was deleted in 1950"], "correctIndex": 2, "explanation": "Constitutional democracies carefully balance equal treatment for all with protective safeguards for smaller cultural/linguistic groups.", "ncertRef": "CHS Conceptual • Minority Safeguards"}, {"id": 93, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Easy", "question": "If a community speaking a tribal or regional language wants to publish books and run a school to keep its script alive, which right protects this?", "options": ["Fundamental Duty to pay taxes", "Cultural and Educational Rights (Articles 29–30)", "Abolition of Titles (Article 18)", "Right against Exploitation (Articles 23–24)"], "correctIndex": 1, "explanation": "Article 29 expressly protects every section of citizens having a distinct language, script, or culture.", "ncertRef": "CHS Application • Cultural Rights"}, {"id": 94, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Medium", "question": "If a citizen's Right to Equality or Right to Freedom is violated by a government rule, which institution can enforce their right?", "options": ["The Courts (Supreme Court under Article 32 and High Courts)", "Only foreign embassies", "No institution can question government rules", "Only the village grocery shop"], "correctIndex": 0, "explanation": "The independent Judiciary acts as the guardian and protector of Fundamental Rights.", "ncertRef": "CHS Core • Role of Judiciary"}, {"id": 95, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Easy", "question": "On School Culture Day, a student named Rukmini wears her village's traditional dress and classmates laugh at her. Which values are they failing to respect?", "options": ["Tax laws", "Traffic rules", "Scientific temper", "Cultural diversity, mutual respect, and inclusion"], "correctIndex": 3, "explanation": "Mocking someone's traditional dress violates respect for cultural diversity and inclusion.", "ncertRef": "CHS Application • Cultural Respect"}, {"id": 96, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Medium", "question": "Which of the following is TRUE about the Right to Freedom of Religion in India?", "options": ["Citizens must get police permission every morning to pray at home", "Every person is free to choose, practise, and share their religion peacefully without forcing others", "Only one official religion is allowed in India", "People can force neighbours to convert by threat"], "correctIndex": 1, "explanation": "Religious freedom includes personal choice and peaceful practice, while prohibiting coercion or forced conversion.", "ncertRef": "CHS Core • Freedom of Religion"}, {"id": 97, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Hard", "question": "Match the Article with its Fundamental Right:\n(i) Articles 25–28 — (ii) Articles 29–30 — (iii) Article 32", "options": ["(i) Duties — (ii) Panchayats — (iii) Elections", "(i) Freedom of Religion — (ii) Cultural & Educational Rights — (iii) Constitutional Remedies", "(i) Equality — (ii) Exploitation — (iii) Freedom", "(i) Education — (ii) Titles — (iii) Untouchability"], "correctIndex": 1, "explanation": "Articles 25–28 cover Religion, 29–30 cover Cultural & Educational Rights, and 32 covers Constitutional Remedies.", "ncertRef": "CHS Match Check • Articles 25–32"}, {"id": 98, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Medium", "question": "Why is it important to respect other people's religions in a diverse country like India?", "options": ["It prevents conflict, upholds everyone's dignity, and strengthens national unity and peace", "Only because tourists visit temples", "Because religion is banned in public life", "Because everyone follows the exact same festival"], "correctIndex": 0, "explanation": "Mutual respect lets citizens of all beliefs live together harmoniously as equals.", "ncertRef": "CHS Conceptual • Harmony"}, {"id": 99, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Hard", "question": "Find the ODD one out among the six Fundamental Rights:", "options": ["Right against Exploitation", "Right to Constitutional Remedies", "Right to Equality", "Fundamental Duty to protect public property"], "correctIndex": 3, "explanation": "Protecting public property is a Fundamental Duty under Article 51A, not one of the six Fundamental Rights.", "ncertRef": "CHS Odd-One-Out • Rights vs Duties"}, {"id": 100, "topic": "Religion, Cultural Rights & Remedies", "difficulty": "Hard", "question": "Assertion (A): Dr. B. R. Ambedkar called Article 32 the heart and soul of the Indian Constitution.\nReason (R): Article 32 empowers citizens to move the Supreme Court to enforce their Fundamental Rights if violated.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is false, but R is true", "A is true, but R is false"], "correctIndex": 0, "explanation": "Judicial enforcement under Article 32 turns constitutional rights into living guarantees.", "ncertRef": "CHS Assertion-Reason • Article 32"}, {"id": 101, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Easy", "question": "In which Part and Article of the Indian Constitution are the Fundamental Duties listed?", "options": ["Part IV-A, Article 51A", "Part II, Article 5", "Part III, Article 32", "Part III, Article 14"], "correctIndex": 0, "explanation": "Fundamental Duties are placed in Part IV-A under a single comprehensive Article — Article 51A.", "ncertRef": "CHS Exam Favorite • Article 51A"}, {"id": 102, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Easy", "question": "Were Fundamental Duties originally present when the Constitution of India came into effect in 1950?", "options": ["Yes — all 11 duties were written in 1947", "No — they were added in 2020", "Yes — they were part of Article 14", "No — they were added later in 1976 by a constitutional amendment"], "correctIndex": 3, "explanation": "When the Constitution began in 1950, it had no Fundamental Duties; 10 duties were added in 1976 (42nd Amendment).", "ncertRef": "CHS Exam Favorite • 1976 Amendment"}, {"id": 103, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Easy", "question": "How many Fundamental Duties are listed in Article 51A of the Indian Constitution today?", "options": ["10 Fundamental Duties", "15 Fundamental Duties", "6 Fundamental Duties", "11 Fundamental Duties"], "correctIndex": 3, "explanation": "Initially 10 duties were added in 1976, and an 11th duty was added in 2002 (total 11 today).", "ncertRef": "CHS Exam Favorite • Total Duties"}, {"id": 104, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Medium", "question": "What is the 11th Fundamental Duty added in 2002 (86th Constitutional Amendment)?", "options": ["Every citizen must join the army", "Every citizen must plant 100 mango trees", "Every student must learn three foreign languages", "Parents or guardians must provide opportunities for education to their child (aged 6 to 14 years)"], "correctIndex": 3, "explanation": "The 11th duty (Article 51A(k)) pairs with Article 21A so parents/guardians ensure schooling for children aged 6–14.", "ncertRef": "CHS Exam Favorite • 11th Duty (2002)"}, {"id": 105, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Easy", "question": "Standing silently and respectfully when the National Anthem plays during school assembly is an example of which Fundamental Duty?", "options": ["To abide by the Constitution and respect the National Flag and National Anthem", "To protect historical monuments only", "To pay income tax", "To develop scientific temper"], "correctIndex": 0, "explanation": "Article 51A(a) reminds citizens to respect our Constitution and national symbols.", "ncertRef": "CHS Core • Article 51A(a)"}, {"id": 106, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Easy", "question": "On a school trip to an ancient fort, stopping a friend from scratching names on the fort wall fulfils which Fundamental Duty?", "options": ["To abolish untouchability", "To defend the country in war", "To value and preserve the rich heritage of our composite culture", "To run a school library"], "correctIndex": 2, "explanation": "Protecting monuments and cultural heritage is a key duty under Article 51A(f).", "ncertRef": "CHS Application • Heritage Duty"}, {"id": 107, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Easy", "question": "Planting trees in the neighbourhood and placing water bowls for stray dogs in summer demonstrates which Fundamental Duty?", "options": ["To strive for excellence in sports", "To respect the National Flag", "To protect and improve the natural environment and have compassion for living creatures", "To follow the ideals of the freedom struggle"], "correctIndex": 2, "explanation": "Article 51A(g) calls on citizens to care for forests, lakes, rivers, wildlife, and show compassion to animals.", "ncertRef": "CHS Application • Environment & Compassion"}, {"id": 108, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Medium", "question": "Demonstrating to a community how simple filtration followed by boiling purifies drinking water (instead of merely memorizing notes) reflects which Fundamental Duty?", "options": ["To respect the National Anthem", "To develop scientific temper, humanism, and the spirit of inquiry and reform", "To preserve ancient forts", "To protect public benches"], "correctIndex": 1, "explanation": "Scientific temper (Article 51A(h)) means questioning, testing, and applying science for human welfare.", "ncertRef": "CHS Exam Favorite • Scientific Temper"}, {"id": 109, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Easy", "question": "After losing a school football match, reminding angry teammates NOT to break school benches fulfils which Fundamental Duty?", "options": ["To earn foreign currency", "To cherish freedom struggle ideals", "To safeguard public property and abjure (give up) violence", "To promote linguistic pride only"], "correctIndex": 2, "explanation": "Article 51A(i) urges citizens to protect public property (buses, trains, schools, parks) and avoid violence.", "ncertRef": "CHS Application • Public Property"}, {"id": 110, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Medium", "question": "When NCC cadets rescue stranded villagers and distribute food packets during a flood, they are practising which Fundamental Duty?", "options": ["To develop scientific temper", "To defend the country and render national service when called upon to do so", "To write on fort walls", "To start a reading club"], "correctIndex": 1, "explanation": "Article 51A(d) includes serving the nation and helping fellow citizens during emergencies and disasters.", "ncertRef": "CHS Application • National Service"}, {"id": 111, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Easy", "question": "Stopping classmates from teasing a girl and reporting bullying to the teacher upholds which Fundamental Duty?", "options": ["To build ramps", "To collect plastic wrappers", "To pay electricity bills", "To promote harmony and renounce practices derogatory to the dignity of women"], "correctIndex": 3, "explanation": "Article 51A(e) specifically calls for brotherhood/harmony and rejecting anything that insults women's dignity.", "ncertRef": "CHS Application • Dignity of Women"}, {"id": 112, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Medium", "question": "Students implementing waste segregation across their entire school after a class discussion exemplifies which Fundamental Duty?", "options": ["To strive towards excellence in all spheres of individual and collective activity", "To open minority schools", "To abolish titles", "To travel across states"], "correctIndex": 0, "explanation": "Article 51A(j) encourages striving for excellence individually and together so the nation progresses.", "ncertRef": "CHS Application • Striving for Excellence"}, {"id": 113, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Medium", "question": "In ancient Indian thought, which Sanskrit term is often translated as 'duty', though it carries a wider meaning of whatever upholds and benefits society?", "options": ["Swarajya", "Dharma", "Adhikara", "Chauth"], "correctIndex": 1, "explanation": "Dharma encompasses duty, righteousness, ethics, and actions that sustain family, society, and Nature.", "ncertRef": "CHS High-Yield • Indian Heritage"}, {"id": 114, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Hard", "question": "What does the ancient Indian concept of 'Rina' (or 'debt') signify in relation to duty?", "options": ["A tax collected by British officers", "The gratitude and duties we owe from birth to parents/ancestors, gurus, fellow humans, devatas, and Nature", "A bank loan taken with high interest", "A punishment for breaking traffic rules"], "correctIndex": 1, "explanation": "The ancient idea of rina reminds us that we receive nourishment and knowledge from family, teachers, society, and Nature, creating a lifelong duty to give back.", "ncertRef": "CHS Exam Favorite • Rina Concept"}, {"id": 115, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Hard", "question": "In ancient Indian texts, what did the word 'Adhikara' originally refer to before modern universal rights?", "options": ["A list of 11 Fundamental Duties", "Universal voting rights for every 18-year-old", "Competence, capacity, or authority to perform a task — except that Dharma gave everyone the right to justice", "A type of medieval fort tax"], "correctIndex": 2, "explanation": "Historically, adhikara meant earned competence/authority, whereas modern constitutional rights are guaranteed universally to all citizens.", "ncertRef": "CHS High-Yield • Adhikara vs Modern Rights"}, {"id": 116, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Medium", "question": "When classmates speaking different regional languages learn friendly phrases from each other's languages instead of arguing, they fulfil which duty?", "options": ["To safeguard public property", "To ensure child education", "To uphold and protect the sovereignty, unity, and integrity of India (and promote harmony)", "To develop scientific temper"], "correctIndex": 2, "explanation": "Celebrating linguistic diversity builds unity in diversity (Article 51A(c) & (e)).", "ncertRef": "CHS Application • Unity in Diversity"}, {"id": 117, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Medium", "question": "Watching a play on Shaheed Bhagat Singh and deciding to speak up against bullying in school reflects which Fundamental Duty?", "options": ["To cherish and follow the noble ideals that inspired our national struggle for freedom", "To pay taxes", "To plant trees", "To protect ancient monuments"], "correctIndex": 0, "explanation": "Standing against injustice and courageously helping others keeps freedom fighters' ideals alive (Article 51A(b)).", "ncertRef": "CHS Application • Freedom Struggle Ideals"}, {"id": 118, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Easy", "question": "Why did residents of Green Park Colony (parents, children, and senior citizens) spend their Sunday morning cleaning the park, planting saplings, and putting water bowls for street dogs?", "options": ["Because they wanted to build a factory", "Because the police threatened to arrest them", "Because they were forced by bonded labour", "Because citizenship duties include caring for our neighbourhood, community, animals, and environment"], "correctIndex": 3, "explanation": "Everyday civic duty builds cleaner, healthier, and happier neighbourhoods without waiting for someone else.", "ncertRef": "CHS Core • Community Duty"}, {"id": 119, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Medium", "question": "In which year was the 10th Fundamental Duty joined by the 11th Fundamental Duty on children's education?", "options": ["1950", "2019", "2002 (after the original 10 were added in 1976)", "1947"], "correctIndex": 2, "explanation": "1976 introduced 10 Fundamental Duties; 2002 added the 11th duty regarding education for ages 6–14.", "ncertRef": "CHS High-Yield • Important Years"}, {"id": 120, "topic": "Fundamental Duties & Indian Heritage", "difficulty": "Hard", "question": "Assertion (A): Fundamental Duties remind citizens that enjoying rights goes hand in hand with contributing to the nation's well-being.\nReason (R): Unlike Fundamental Rights, Fundamental Duties are listed in Part IV-A (Article 51A) as moral and civic responsibilities.", "options": ["Both A and R are true, and R supports A", "A is true, but R is false", "A is false, but R is true", "Both A and R are false"], "correctIndex": 0, "explanation": "Fundamental Rights empower citizens legally, while Fundamental Duties guide citizens morally and socially.", "ncertRef": "CHS Assertion-Reason • Duties"}, {"id": 121, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Easy", "question": "Why are Rights and Duties often called 'two sides of the same coin'?", "options": ["Because every right we enjoy carries a matching duty to respect others' rights and use freedom responsibly", "Because coins have the National Anthem written on them", "Because rights and duties are enemies that cancel each other", "Because only rich people have rights and only poor people have duties"], "correctIndex": 0, "explanation": "If everyone demanded rights while ignoring duties, no one's rights would remain safe.", "ncertRef": "CHS Exam Favorite • Rights & Duties"}, {"id": 122, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Medium", "question": "How do Fundamental Rights and Fundamental Duties differ in terms of legal enforcement?", "options": ["Neither Rights nor Duties exist in the Constitution", "Fundamental Duties can send someone straight to the Supreme Court, while Rights cannot", "Fundamental Rights are legally enforceable in courts, whereas Fundamental Duties are primarily moral and social responsibilities", "Both are enforced only by school prefects"], "correctIndex": 2, "explanation": "If a right is violated, you can seek court remedies; duties rely mainly on civic conscience and social responsibility (unless backed by specific laws like anti-littering or flag rules).", "ncertRef": "CHS High-Yield • Legal vs Moral"}, {"id": 123, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Easy", "question": "If I have the RIGHT to be treated with respect by my classmates, what is my matching DUTY?", "options": ["To tease new students about their accents", "To ignore everyone in class", "To demand respect without respecting anyone", "To treat all my classmates and others with respect"], "correctIndex": 3, "explanation": "Respect is mutual: my right to dignity depends on everyone practising the duty to respect others.", "ncertRef": "CHS Core • Matching Duties"}, {"id": 124, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Easy", "question": "If I have the RIGHT to express my opinions freely, what is my matching DUTY?", "options": ["To spread false rumours online", "To shout down anyone who disagrees with me", "To listen respectfully to other people's views without causing harm, even when I disagree", "To force friends to join my protest"], "correctIndex": 2, "explanation": "Free expression in a democracy requires listening patiently and respecting peaceful disagreement.", "ncertRef": "CHS Core • Matching Duties"}, {"id": 125, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Easy", "question": "What is the matching DUTY that pairs directly with a student's RIGHT TO EDUCATION?", "options": ["Throwing chocolate wrappers on the school playground", "Stopping younger sisters from going to school", "Breaking classroom desks after a match", "Attending school sincerely, learning with curiosity, respecting teachers/peers, and helping others access education"], "correctIndex": 3, "explanation": "Rights flourish when students value learning and help make schools welcoming and clean.", "ncertRef": "CHS Application • Right to Education"}, {"id": 126, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Medium", "question": "Ravi disagrees with a school protest march and chooses not to join, so some classmates threaten to exclude him from their group. Which right of Ravi is being violated?", "options": ["His Right to Childline 1098", "His Right to drive a car", "His Right to Freedom of opinion and conscience (and non-exclusion)", "His Duty to pay taxes"], "correctIndex": 2, "explanation": "Freedom of expression includes the freedom NOT to join a march you disagree with, without facing bullying or exclusion.", "ncertRef": "CHS Application • Civic Scenarios"}, {"id": 127, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Easy", "question": "During recess, students throw chocolate wrappers on the playground instead of the dustbin. Which duty are they neglecting?", "options": ["Duty to keep surroundings clean and protect the environment", "Cultural Rights of Minorities", "Right to Freedom of Religion", "Right to Equality"], "correctIndex": 0, "explanation": "Cleanliness in shared school spaces is an everyday civic duty toward our community and environment.", "ncertRef": "CHS Application • Cleanliness Duty"}, {"id": 128, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Medium", "question": "In a mock youth parliament using an online voting app, students from remote villages are also able to share their ideas. What democratic value does this show?", "options": ["Inclusion and active democratic participation using technology", "Exploitation", "Invisible discrimination", "Abolition of titles"], "correctIndex": 0, "explanation": "Digital tools used thoughtfully can remove geographical barriers and include rural or remote voices.", "ncertRef": "CHS Application • Technology & Democracy"}, {"id": 129, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Medium", "question": "What would happen in a society if EVERY citizen demanded their rights while completely ignoring their duties?", "options": ["Public spaces would become dirty/unsafe, laws would break down, and everyone's rights would soon be violated", "Roads and parks would repair themselves", "Courts would no longer be needed", "Society would become twice as peaceful and clean"], "correctIndex": 0, "explanation": "One person's duty (like obeying traffic lights or not polluting) protects another person's right (like safety and clean air).", "ncertRef": "CHS Conceptual • Balance of Rights & Duties"}, {"id": 130, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Easy", "question": "Which of the following pairs correctly matches a RIGHT with its corresponding DUTY?", "options": ["Right to public parks ↔ Duty to break park swings", "Right to education ↔ Duty to tear library books", "Right to clean environment ↔ Duty not to litter and to plant/care for trees", "Right to free speech ↔ Duty to spread hate online"], "correctIndex": 2, "explanation": "Every right stays healthy only when citizens perform the matching responsibility.", "ncertRef": "CHS Match Check • Rights & Duties"}, {"id": 131, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Medium", "question": "How can social media and online platforms make practising good citizenship HARDER if misused?", "options": ["They eliminate all electricity bills", "They can spread rumours, cyberbullying, hate speech, and invisible exclusion quickly", "They replace schools completely", "They automatically build wheelchair ramps"], "correctIndex": 1, "explanation": "While technology helps participation, online bullying and misinformation harm respect and unity.", "ncertRef": "CHS Conceptual • Digital Citizenship"}, {"id": 132, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Medium", "question": "If a local factory dumps toxic waste into a river used by villagers for drinking water, which right of the villagers is violated and which duty did the factory ignore?", "options": ["Violated: Minority school rights; Ignored: Scientific temper", "Violated: Right to Life (clean environment & health); Ignored: Duty to protect the environment", "Violated: Right to Titles; Ignored: Duty to respect the Flag", "No right or duty is involved"], "correctIndex": 1, "explanation": "Clean water and a pollution-free environment are vital parts of Article 21, and protecting rivers is a duty under Article 51A(g).", "ncertRef": "CHS Application • Environment & Law"}, {"id": 133, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Easy", "question": "Which everyday habit best shows responsible citizenship at home?", "options": ["Throwing plastic into street drains", "Playing loud horns near hospitals", "Saving water and electricity and segregating wet and dry waste", "Leaving taps open all day"], "correctIndex": 2, "explanation": "Conserving water, energy, and managing waste responsibly are practical civic duties every student can practise daily.", "ncertRef": "CHS Core • Everyday Habits"}, {"id": 134, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Medium", "question": "A student is always honest, follows traffic signals while cycling, and helps an elderly neighbour cross the road. This shows:", "options": ["Moral and civic responsibility in everyday life", "Unreasonable restriction", "Discrimination", "Exploitation"], "correctIndex": 0, "explanation": "Everyday kindness and rule-following strengthen trust and safety in society.", "ncertRef": "CHS Core • Civic Virtue"}, {"id": 135, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Easy", "question": "Can any citizen demand that the government protect their rights while refusing to obey traffic laws or pay taxes?", "options": ["Only if they live in a big city", "No — responsible citizenship requires fulfilling duties alongside claiming rights", "Yes — taxes are optional for billionaires", "Yes — duties apply only to teachers"], "correctIndex": 1, "explanation": "Rights and duties are inseparable; laws and public services survive through citizens' cooperation.", "ncertRef": "CHS Conceptual • Civic Responsibility"}, {"id": 136, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Medium", "question": "Why is listening with empathy important in a democracy?", "options": ["It replaces the Constitution", "It stops people from voting", "It helps everyone feel valued and safe, resolves disagreements peacefully, and prevents exclusion", "It forces everyone to think identically"], "correctIndex": 2, "explanation": "Empathy turns legal equality into genuine social harmony.", "ncertRef": "CHS Core • Empathy"}, {"id": 137, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Medium", "question": "When can a conflict seem to arise between a citizen's individual freedom and a duty toward others?", "options": ["When a student drinks clean water", "When someone reads a book silently in a library", "When farmers grow wheat", "When someone wants to burst loud firecrackers late at night (freedom/celebration) while neighbours need quiet sleep and clean air"], "correctIndex": 3, "explanation": "In such conflicts, responsible citizens adjust their freedom so they do not harm others' health or peace.", "ncertRef": "CHS Conceptual • Resolving Conflicts"}, {"id": 138, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Easy", "question": "Which of the following strengthens democracy the MOST?", "options": ["Excluding poor children from libraries", "Silencing students who ask questions", "Enabling and welcoming the participation of all people fairly", "Ignoring minority languages"], "correctIndex": 2, "explanation": "Democracy thrives when every citizen's voice and participation are respected.", "ncertRef": "CHS Core • Democracy"}, {"id": 139, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Hard", "question": "Which statement is INCORRECT about Rights and Duties?", "options": ["Duties remind citizens to use freedom responsibly", "Citizens can approach courts if Fundamental Rights are violated", "Duties are enforced by arresting anyone who forgets to plant a tree, whereas Rights have no legal protection", "Rights allow citizens to live with dignity and safety"], "correctIndex": 2, "explanation": "It is actually Fundamental Rights that are directly enforceable in courts, while Fundamental Duties are moral/civic guides.", "ncertRef": "CHS Exam Drill • True/False"}, {"id": 140, "topic": "Rights & Duties: Two Sides of a Coin", "difficulty": "Hard", "question": "Assertion (A): Can we enjoy our Fundamental Rights safely if nobody performs their Fundamental Duties?\nReason (R): No — fulfilling duties such as respecting others, obeying laws, and protecting nature is what keeps everyone's rights safe.", "options": ["Duties exist only to punish students", "Both the question's premise and R correctly explain why rights and duties cannot be separated", "Rights survive easily even if everyone breaks laws", "Rights and duties have no connection"], "correctIndex": 1, "explanation": "Every citizen's duty is the shield that protects every other citizen's rights.", "ncertRef": "CHS Assertion-Reason • Interdependence"}, {"id": 141, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Easy", "question": "What is 'discrimination'?", "options": ["Unfair or unequal treatment of a person or group based on caste, religion, gender, appearance, disability, or economic background", "Selecting the best actor after fair auditions", "Giving extra help like Braille books to a blind student", "Building wheelchair ramps in schools"], "correctIndex": 0, "explanation": "Judging or excluding someone based on identity or background rather than fairness is discrimination — both unethical and illegal.", "ncertRef": "CHS Core • Discrimination"}, {"id": 142, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Easy", "question": "In a school play audition, classmates whisper that Sanya 'does not fit the image' of a lead actor because of her looks, though her acting is brilliant. This is an example of:", "options": ["Constitutional remedy", "Equity", "Scientific temper", "Discrimination based on physical appearance"], "correctIndex": 3, "explanation": "Judging talent by looks rather than ability and effort is unfair appearance-based discrimination.", "ncertRef": "CHS Application • Discrimination"}, {"id": 143, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Medium", "question": "What is 'invisible (indirect) discrimination', and why is it especially difficult to deal with?", "options": ["Subtle exclusion — like ignoring someone, whispering, or leaving them out of a group — which is hard to prove and penalise legally", "Passing a written law in Parliament", "Providing ramps for wheelchairs", "Openly putting up a 'No Entry' signboard"], "correctIndex": 0, "explanation": "Unlike overt bans, subtle taunts or social exclusion hurt deeply yet are hard to prove in court, making empathy and awareness vital.", "ncertRef": "CHS Exam Favorite • Invisible Discrimination"}, {"id": 144, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Easy", "question": "A group of boys mocks Rohan's weight with a rude nickname and blocks him from playing football. This is:", "options": ["Equity", "Active inclusion", "Right to Constitutional Remedies", "Visible discrimination and bullying based on physical appearance"], "correctIndex": 3, "explanation": "Publicly mocking and excluding a classmate is visible discrimination that harms both mental and physical well-being.", "ncertRef": "CHS Application • Bullying"}, {"id": 145, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Medium", "question": "Mina cannot afford an expensive school trip, and her classmates whisper that she 'is not of their status' and ignore her. This is an example of:", "options": ["Religious freedom", "Invisible discrimination based on economic background", "Cultural inclusion", "Scientific inquiry"], "correctIndex": 1, "explanation": "Excluding or looking down on someone due to family income is unfair economic discrimination.", "ncertRef": "CHS Application • Economic Discrimination"}, {"id": 146, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Easy", "question": "Who was the pioneering 19th-century social reformer from Maharashtra who opened one of India's first schools for girls despite facing abuse and mud thrown at her?", "options": ["Ahilyabai Holkar", "Sarojini Naidu", "Anandibai Joshi", "Savitribai Phule (alongside her husband Jyotiba Phule)"], "correctIndex": 3, "explanation": "Savitribai Phule and Jyotiba Phule fought caste and gender discrimination in the mid-19th century to educate girls and children of all backgrounds.", "ncertRef": "CHS Exam Favorite • Savitribai Phule"}, {"id": 147, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Medium", "question": "Who overcame severe social opposition and personal tragedy in the 19th century to travel abroad and graduate from the Woman's Medical College of Pennsylvania as one of India's earliest women doctors?", "options": ["Kalpana Chawla", "Anandibai Joshi", "Savitribai Phule", "Maharani Tarabai"], "correctIndex": 1, "explanation": "Married at age 9 and losing her infant due to lack of medical care, Anandibai Joshi determinedly studied medicine in the USA to serve mothers and children.", "ncertRef": "CHS Exam Favorite • Anandibai Joshi"}, {"id": 148, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Easy", "question": "What does 'Inclusion' truly mean in a school or society?", "options": ["Separating students by family income", "Giving only identical rules without helping differently abled students", "Allowing only one language in the library", "Creating an environment where everyone feels welcomed, respected, valued, and has equal access to opportunities"], "correctIndex": 3, "explanation": "Inclusion goes beyond formal rules — it actively removes barriers so nobody is left behind.", "ncertRef": "CHS Core • Meaning of Inclusion"}, {"id": 149, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Medium", "question": "When librarian Smt. Amita saw few students borrowing English books, she added regional-language books, storytelling, and puppetry, and membership soared. What principle did she practise?", "options": ["Discrimination", "Exploitation", "Abolition of titles", "Inclusion — removing language barriers so all students felt welcomed"], "correctIndex": 3, "explanation": "Including regional languages welcomed students regardless of English fluency, turning the club into a joyful space for all.", "ncertRef": "CHS Application • Inclusion in Action"}, {"id": 150, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Easy", "question": "Which of the following is a practical example of making a school building inclusive for students using wheelchairs?", "options": ["Locking the ground-floor classrooms", "Removing all library tables", "Building smooth wheelchair ramps alongside staircases", "Adding steeper stairs with no railings"], "correctIndex": 2, "explanation": "Ramps ensure children with mobility disabilities can enter halls, classrooms, and stages independently and with dignity.", "ncertRef": "CHS Core • Accessibility"}, {"id": 151, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Medium", "question": "If a classmate takes a little longer to read or write during group work because they learn differently, what is the most inclusive response?", "options": ["Finish the project without them and leave their name out", "Be patient, explain clearly, and make sure they get a fair chance to contribute and speak", "Laugh at their reading speed", "Ask the teacher to remove them from class"], "correctIndex": 1, "explanation": "Patience, peer support, and equal voice make classrooms truly inclusive for every learner.", "ncertRef": "CHS Application • Classroom Inclusion"}, {"id": 152, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Medium", "question": "Why does someone who discriminates against another person or group 'ethically cease to be an active citizen of India'?", "options": ["Because they breach the very core values of the Indian Constitution — respect, equality, and unity", "Because they forget how to read maps", "Because they cannot use public buses", "Because they lose their school uniform"], "correctIndex": 0, "explanation": "True citizenship means living constitutional values of dignity and non-discrimination every day.", "ncertRef": "CHS Conceptual • Constitutional Ethos"}, {"id": 153, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Easy", "question": "If a school stops girls from joining a mathematics or science club, what is the right action to take?", "options": ["Make fun of the girls", "Close the science club for everyone", "Accept that girls cannot study science", "Speak respectfully with teachers/principal citing equal rights so girls are welcomed into the club"], "correctIndex": 3, "explanation": "Denying girls access to science or maths clubs is gender discrimination and violates the Right to Equality.", "ncertRef": "CHS Application • Gender Equality"}, {"id": 154, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Medium", "question": "How does inclusion go BEYOND simply providing legal reservations?", "options": ["Inclusion cancels all Fundamental Rights", "Inclusion means building higher walls between groups", "Inclusion ensures everyday social acceptance, respect, barrier-free facilities, and supportive attitudes — not just seats on paper", "Inclusion applies only to sports teams"], "correctIndex": 2, "explanation": "While laws and reservations open doors, inclusion creates a warm, supportive culture inside classrooms and workplaces.", "ncertRef": "CHS Conceptual • Inclusion vs Mere Rules"}, {"id": 155, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Medium", "question": "Why did Savitribai Phule face mud-throwing and insults while walking to teach girls in the mid-1800s?", "options": ["Because she lived in New Zealand", "Because schools were banned by the Supreme Court", "Because conservative sections opposed both women's education and a teacher from the Mali community", "Because she refused to teach mathematics"], "correctIndex": 2, "explanation": "Savitribai Phule's courage broke double barriers of gender and caste discrimination in Indian education.", "ncertRef": "CHS High-Yield • Social Reformers"}, {"id": 156, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Easy", "question": "Which of the following is NOT a valid ground on which anyone can be excluded from a public celebration or school club?", "options": ["Willingness to participate", "Following fair tryouts for all", "Caste, religion, gender, skin colour, or family wealth", "Respecting safety rules"], "correctIndex": 2, "explanation": "Identity-based exclusion is unconstitutional; fair, open opportunities must be available to all.", "ncertRef": "CHS Core • Non-Discrimination"}, {"id": 157, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Medium", "question": "How do Fundamental Rights and Fundamental Duties work TOGETHER to build an inclusive society?", "options": ["Rights guarantee equal access and protection by law, while Duties encourage citizens to respect diversity and support others", "Rights apply only to adults and Duties only to children", "They work against each other", "Only Duties are written in the Constitution"], "correctIndex": 0, "explanation": "Together, legal rights and caring civic duties remove both visible and invisible barriers.", "ncertRef": "CHS Conceptual • Rights + Duties = Inclusion"}, {"id": 158, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Hard", "question": "Compare Equality, Equity, and Inclusion: which statement is MOST accurate?", "options": ["Equality gives identical support; Equity gives tailored support based on need; Inclusion removes barriers so everyone belongs together", "All three prohibit ramps and Braille books", "Equality means exclusion; Equity means ignoring needs; Inclusion means sameness", "Only Equality is legal in India"], "correctIndex": 0, "explanation": "Understanding the progression from Equality → Equity → Inclusion is a central takeaway of Class 8 Civics.", "ncertRef": "CHS Exam Favorite • Equality, Equity & Inclusion"}, {"id": 159, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Hard", "question": "Find the ODD one out among actions that promote INCLUSION:", "options": ["Refusing to sit next to a classmate because of their economic background", "Providing Braille books and tactile maps", "Building wheelchair ramps at an exhibition hall", "Adding regional-language books to a school library"], "correctIndex": 0, "explanation": "Refusing to sit next to someone due to economic background is discrimination, whereas the other three actively include everyone.", "ncertRef": "CHS Odd-One-Out • Inclusion"}, {"id": 160, "topic": "Discrimination, Inclusion & Social Reformers", "difficulty": "Hard", "question": "Assertion (A): Invisible discrimination is often harder to stop than visible discrimination.\nReason (R): Subtle taunts, whispering, or silently leaving someone out of a project are difficult to prove and penalise legally.", "options": ["Both A and R are true, but R is NOT the correct explanation of A", "A is false, but R is true", "Both A and R are true, and R is the correct explanation of A", "A is true, but R is false"], "correctIndex": 2, "explanation": "Because subtle exclusion rarely leaves legal evidence, building empathy and inclusive habits in classrooms is essential.", "ncertRef": "CHS Assertion-Reason • Invisible Discrimination"}]};
